// Meta WhatsApp Webhook Signature Verification
// Production security: Verify webhook signature to prevent unauthorized requests
// Reference: Meta WhatsApp Business API security requirements
// Format: X-Hub-Signature-256: sha256=<hash>

const crypto = require('crypto');
const input = $input.item.json;
const headers = input.headers || {};
const rawBody = input.raw_body || JSON.stringify(input);

// Meta sends signature in X-Hub-Signature-256 header with format: sha256=<hash>
const signatureHeader = headers['X-Hub-Signature-256'] 
  || headers['x-hub-signature-256']
  || headers['X-Hub-Signature']
  || headers['x-hub-signature'];

// Extract hash from 'sha256=<hash>' format
let receivedSignature = null;
if (signatureHeader) {
  const match = signatureHeader.match(/sha256=(.+)/i);
  if (match) {
    receivedSignature = match[1];
  } else {
    // Fallback: assume entire header is the hash
    receivedSignature = signatureHeader;
  }
}

// Use Meta App Secret (from WhatsApp Business API settings)
const appSecret = process.env.WHATSAPP_APP_SECRET || process.env.META_APP_SECRET;

if (!receivedSignature) {
  // In development, allow webhooks without signature (for testing)
  if (process.env.NODE_ENV === 'development' || process.env.ALLOW_UNSIGNED_WEBHOOKS === 'true') {
    return {
      valid: true,
      signature_verified: false,
      warning: 'Webhook signature not verified (development mode)',
      ...input
    };
  }

  return {
    valid: false,
    error: 'Missing X-Hub-Signature-256 header',
    statusCode: 401,
    security_event: 'missing_signature'
  };
}

if (!appSecret) {
  return {
    valid: false,
    error: 'WHATSAPP_APP_SECRET or META_APP_SECRET not configured',
    statusCode: 500,
    security_event: 'config_error'
  };
}

// Meta signature: HMAC-SHA256(payload, app_secret) in hex format
const payloadString = typeof rawBody === 'string' ? rawBody : JSON.stringify(rawBody);

const expectedSignature = crypto
  .createHmac('sha256', appSecret)
  .update(payloadString)
  .digest('hex');

// Constant-time comparison (prevent timing attacks)
let isValid = false;
try {
  isValid = crypto.timingSafeEqual(
    Buffer.from(receivedSignature, 'hex'),
    Buffer.from(expectedSignature, 'hex')
  );
} catch (e) {
  // Signature format mismatch or invalid hex
  isValid = false;
}

if (!isValid) {
  return {
    valid: false,
    error: 'Invalid Meta WhatsApp signature',
    statusCode: 401,
    security_event: 'invalid_signature',
    received_sig: receivedSignature.substring(0, 20) + '...',
    expected_sig: expectedSignature.substring(0, 20) + '...'
  };
}

return {
  valid: true,
  signature_verified: true,
  ...input
};

// BUSINESS LOGIC: Classify message type
// Architecture: See docs/NATIVE_INTEGRATIONS.md

const text = ($input.item.json.message_text || '').toLowerCase();
let messageType = 'unknown';

// Order keywords (English, Swahili, Sheng)
if (text.match(/order|nataka|taka|nimtaki|buy|want|nunua/i)) {
  messageType = 'order';
}
// Payment query
else if (text.match(/payment|paid|pesa|lipa|malipo/i)) {
  messageType = 'payment_query';
}
// Status query
else if (text.match(/status|where|delivery|wapi|hali/i)) {
  messageType = 'status_query';
}
// Support
else if (text.match(/help|support|saaidie|msaada|assist/i)) {
  messageType = 'support';
}

return { 
  message_type: messageType, 
  ...$input.item.json 
};

// BUSINESS LOGIC: Determine user type and conversation window
// Architecture: See docs/NATIVE_INTEGRATIONS.md

const buyerResult = $('Check Buyer').first()?.json || [];
const sellerResult = $('Check Seller').first()?.json || [];
const conversationData = $('Query Conversation State').first()?.json || [];
const messageData = $input.item.json;

let userType = 'new_user';
if (sellerResult.length > 0) {
  userType = 'seller';
} else if (buyerResult.length > 0) {
  userType = 'buyer';
}

// Check conversation window (24h from last message)
const conversation = conversationData[0];
const now = new Date();
const expiresAt = conversation?.conversation_window_expires_at 
  ? new Date(conversation.conversation_window_expires_at) 
  : null;
const sessionAllowed = expiresAt && expiresAt > now;

// Determine priority
let priority = 'low';
if (['order', 'payment_query'].includes(messageData.message_type)) {
  priority = 'high';
} else if (['status_query', 'support'].includes(messageData.message_type)) {
  priority = 'medium';
}

// Determine fallback allowed
const fallbackAllowed = ['order', 'payment_query', 'status_query'].includes(messageData.message_type);

return {
  ...messageData,
  user_type: userType,
  priority: priority,
  session_allowed: sessionAllowed,
  fallback_allowed: fallbackAllowed
};

// Error Handler: Classify and prepare error for logging
// Industry standard error handling pattern

const error = $input.item.json.error || {};
const nodeName = $input.item.json.node?.name || 'unknown_node';
const errorMessage = error.message || 'Unknown error';
const errorCode = error.code || error.status || 'UNKNOWN';
const errorStack = error.stack || null;

// Classify error
let errorType = 'NEEDS_REVIEW';
let severity = 'ERROR';

if (
  errorCode === 'ECONNREFUSED' ||
  errorCode === 'ETIMEDOUT' ||
  errorCode === 'ENOTFOUND' ||
  errorCode === 429 ||
  errorCode === 503 ||
  errorCode === 502 ||
  errorMessage.toLowerCase().includes('timeout') ||
  errorMessage.toLowerCase().includes('network')
) {
  errorType = 'RETRYABLE';
} else if (
  errorCode === 401 ||
  errorCode === 403 ||
  errorMessage.toLowerCase().includes('unauthorized')
) {
  errorType = 'CRITICAL';
  severity = 'CRITICAL';
} else if (
  errorCode === 400 ||
  errorCode === 422 ||
  errorMessage.toLowerCase().includes('validation')
) {
  errorType = 'NEEDS_REVIEW';
}

// Get context from previous nodes
const messageData = $('Extract Message Data').first()?.json || {};
const phone = messageData.phone || 'unknown';

return {
  error_type: errorType,
  severity: severity,
  service_name: 'whatsapp-webhook',
  error_message: errorMessage,
  error_code: errorCode,
  error_stack: errorStack,
  node_name: nodeName,
  phone: phone,
  message_id: messageData.message_id || null,
  context: {
    operation: 'classify_message',
    node: nodeName,
    phone: phone
  },
  status_code: errorCode >= 500 ? 500 : (errorCode >= 400 ? 400 : 500)
};
